import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.Dj7FWXx_.js";const c=JSON.parse('{"title":"执行 QQ 等级加速任务","description":"","frontmatter":{},"headers":[],"relativePath":"api/execute_level_tasks.md","filePath":"api/execute_level_tasks.md","lastUpdated":null}'),l={name:"api/execute_level_tasks.md"};function d(n,e,h,o,p,k){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="执行-qq-等级加速任务" tabindex="-1">执行 QQ 等级加速任务 <a class="header-anchor" href="#执行-qq-等级加速任务" aria-label="Permalink to &quot;执行 QQ 等级加速任务&quot;">​</a></h1><p><code>execute_level_tasks</code> 按数组顺序执行指定的 QQ 等级加速任务；各项错误汇总返回。</p><blockquote><p><strong>当前状态：</strong>“来元宝P图一次”暂不支持。</p></blockquote><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td>self_id</td><td>number</td><td>是</td><td>在线 Android Bot QQ 号</td></tr><tr><td>tasks</td><td>string[]</td><td>是</td><td>非空完整任务标题数组，应从当前不含付费项的面板选择</td></tr></tbody></table><p>原位置参数不变，QQ 等级仍须达到 16 级。等级任务面板不再返回会员推广位及日常、额外分类中的付费任务；调用方不应保存或提交这些标题。擂台任务仅接受标题“创建小游戏擂台并取得成绩”，对应 <code>center_task_id=80</code>，当前仅方块冲刺 v6；没有新增 <code>game</code>、<code>score</code>、<code>time</code> 参数。框架在创建前持久登记本次执行，使用独立执行标识阻止旧请求回写；失败不消耗当天执行资格。</p><p>“去看免费小说”也使用相同 <code>tasks</code> 数组，对应 <code>center_task_id=64</code>。当前 QQ 协议没有客户端可填写的阅读秒数字段；框架按官方两秒心跳持续上报，直到 QQ 返回当日阅读时长不少于 180 秒，再调用阅读器等级任务结算接口，因此一次执行约需三分钟。调用方不要传入阅读时长、伪造时间或在超时后自动重放，最终仍以刷新后的 <code>is_done</code> 为准。</p><p>其余 QQ 基础/额外加速项目也沿用本接口按面板标题执行；调用方不应为单个项目另建插件 action。任务是否可执行以面板 executable/can_execute 为准。</p><p>当前执行由 Go 直接协议上报 1–99 随机整数分数，不运行游戏，不需要 Python、Node、Chrome 或外部 worker 安装。成功还须独立执行 <code>0x916e → 0x9172</code> 刷新确认 QQ task80 完成。仅最终 <code>wx.login</code> 响应确证 <code>authorization_required</code> 才显示“微信未授权登录”。缺少 <code>ilink_buffer</code> 是 QQ 提供的小游戏登录凭证缺失，官方按 <code>FailAuthCommon</code> 通用失败处理，不能据此推断未授权；普通认证或网络失败同样不能推断。Linux amd64 测试站通过 2082083 的一次标准 API Go 直接模式验收；Windows 与 Linux arm64 的完整任务未实测，见<a href="https://github.com/Carlor-Official/Mengka-NT/blob/v2.3.9/docs/arena-level-task.md" target="_blank" rel="noreferrer">小游戏擂台等级任务</a>。</p><p>v2.3.1 起，擂台任务取消每日尝试次数限制。只有 QQ 刷新确认完成才显示“已完成”；执行失败返回错误原因，面板显示“待完成”，允许再次执行。擂台任务不再返回 <code>attempted_today</code>，客户端应以 <code>can_execute</code> 判断本次能否执行。正在执行时保留账号互斥，禁止并发提交；每次新执行重新核验 QQ 状态、当前登录材料和新建条件，不续传旧房间分数。SDK 和页面刷新不自动重试。</p><h2 id="返回" tabindex="-1">返回 <a class="header-anchor" href="#返回" aria-label="Permalink to &quot;返回&quot;">​</a></h2><p>全部执行成功时 Promise 解析为 <code>null</code>；任一任务失败时拒绝并包含任务标题和固定原因。接口成功不生成 QQ 完成或加速数值；擂台成功须当前会话、新房初始空分、上传成功、同房本人本次随机分数读回、退出协议确认和独立 <code>0x916e → 0x9172</code> 等级刷新完成。上传成功不能代替 QQ 最终入账。</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> api.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forProtocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;android&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute_level_tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;创建小游戏擂台并取得成绩&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 免费小说阅读时长由 QQ 服务端按真实心跳累计。</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> api.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forProtocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;android&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute_level_tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;去看免费小说&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><p>SDK 保持 5 分钟等待；框架请求总预算 4 分 45 秒。超时、断线、结果未知均不自动重放。完整面板、过滤与计划功能可使用 <a href="/api/execute_level_task_selection.html">execute_level_task_selection</a>。</p>`,14)])])}const E=s(l,[["render",d]]);export{c as __pageData,E as default};
